<?php
namespace Tests\Feature;
use App\Models\{User,ConnectedAdAccount,Campaign,PerformanceMetric,ConversionDefinition,TypedConversionDaily,OptimizationRun};
use Database\Seeders\RoleAndPermissionSeeder;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Tests\TestCase;
class TypedLeadSourcesTest extends TestCase{
 use DatabaseTransactions;
 private function fixture():array{(new RoleAndPermissionSeeder)->run();$u=User::factory()->create();$u->assignRole('Owner');$a=ConnectedAdAccount::create(['user_id'=>$u->id,'provider'=>'meta','external_account_id'=>uniqid(),'account_name'=>'Fixture','currency'=>'USD','timezone'=>'UTC','access_token'=>'fixture']);$c=Campaign::create(['connected_ad_account_id'=>$a->id,'provider'=>'meta','external_campaign_id'=>uniqid(),'name'=>'Fixture','currency'=>'USD']);return[$u,$a,$c];}
 private function definition(ConnectedAdAccount $a):ConversionDefinition{return ConversionDefinition::create(['connected_ad_account_id'=>$a->id,'external_key'=>'crm_lead','name'=>'CRM lead','kind'=>'lead','counting_method'=>'events','attribution_model'=>'declared_last_click','click_window_days'=>7,'view_window_days'=>0,'source_system'=>'fixture_crm']);}
 public function test_definition_write_is_owned_permission_gated_and_immutable():void{
  [$u,$a]=$this->fixture();$body=['external_key'=>'crm','name'=>'CRM','kind'=>'lead','counting_method'=>'events','attribution_model'=>'last_click','click_window_days'=>7,'view_window_days'=>0,'source_system'=>'manual'];$this->postJson('/api/v1/ad-accounts/'.$a->id.'/conversion-definitions',$body)->assertUnauthorized();$other=User::factory()->create();$this->actingAs($other,'sanctum')->postJson('/api/v1/ad-accounts/'.$a->id.'/conversion-definitions',$body)->assertNotFound();$this->actingAs($u,'sanctum')->postJson('/api/v1/ad-accounts/'.$a->id.'/conversion-definitions',$body)->assertCreated()->assertJsonPath('data.kind','lead');$this->postJson('/api/v1/ad-accounts/'.$a->id.'/conversion-definitions',$body)->assertConflict();$this->getJson('/api/v1/ad-accounts/'.$a->id.'/conversion-definitions')->assertOk()->assertJsonCount(1,'data');
 }
 public function test_aggregate_import_is_idempotent_strict_scoped_and_never_changes_generic_metrics():void{
  [$u,$a,$c]=$this->fixture();$d=$this->definition($a);$this->actingAs($u,'sanctum');$url='/api/v1/ad-accounts/'.$a->id.'/conversion-definitions/'.$d->id.'/daily-import';$row=['entity_id'=>$c->id,'date'=>now()->subDay()->toDateString(),'count'=>3,'currency'=>'USD','timezone'=>'UTC','source_reference'=>'batch-1','retrieved_at'=>now()->format('Y-m-d\TH:i:sP')];$body=['entity_level'=>'campaign','rows'=>[$row]];$this->postJson($url,$body)->assertOk()->assertJsonPath('data.provider_verified',false);$this->postJson($url,$body)->assertOk();$this->assertSame(1,TypedConversionDaily::where('conversion_definition_id',$d->id)->count());$this->assertSame(0,PerformanceMetric::where('connected_ad_account_id',$a->id)->count());$bad=$row;$bad['count']=1.5;$this->postJson($url,['entity_level'=>'campaign','rows'=>[$bad]])->assertUnprocessable();$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row,$row]])->assertUnprocessable();$bad=$row;$bad['currency']='EUR';$this->postJson($url,['entity_level'=>'campaign','rows'=>[$bad]])->assertUnprocessable();[$other,$foreign,$fc]=$this->fixture();$bad=$row;$bad['entity_id']=$fc->id;$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row,$bad]])->assertUnprocessable();$this->assertSame(1,TypedConversionDaily::where('conversion_definition_id',$d->id)->count());
 }
 public function test_leads_fit_uses_only_explicit_definition_and_archives_source_for_replay():void{
  [$u,$a,$c]=$this->fixture();$d=$this->definition($a);for($i=30;$i>=1;$i--){$x=30+(30-$i)*10;$date=now()->subDays($i)->toDateString();PerformanceMetric::create(['metadata'=>['outcome_contract'=>['version'=>'source-outcomes-1','provider'=>'meta','count_metric'=>'synthetic-purchase','value_metric'=>'synthetic-purchase-value','attribution_basis'=>'synthetic-only','value_truth'=>'provider_reported_not_verified_sales','cross_source_equivalence'=>false],'normalization_version'=>'strict-operands-1','metric_definition'=>['normalization'=>'strict-meta-operands-1','account_metadata_source'=>'meta-discovery-explicit-1']],'connected_ad_account_id'=>$a->id,'campaign_id'=>$c->id,'provider'=>'meta','date'=>$date,'spend'=>$x,'impressions'=>1000,'clicks'=>100,'conversions'=>9999,'conversion_value'=>999999,'currency'=>'USD']);TypedConversionDaily::create(['conversion_definition_id'=>$d->id,'entity_level'=>'campaign','entity_id'=>$c->id,'date'=>$date,'count'=>round(50*(1-exp(-.01*$x))),'currency'=>'USD','timezone'=>'UTC','source_reference'=>'batch-1','retrieved_at'=>now()]);}$this->actingAs($u,'sanctum');$base=['entity_level'=>'campaign','objective'=>'MAXIMIZE_LEADS','budget'=>4000,'provider'=>'meta'];$this->postJson('/api/v1/analytics/entity-optimization',$base)->assertUnprocessable();$r=$this->postJson('/api/v1/analytics/entity-optimization',$base+['conversion_definition_id'=>$d->id])->assertOk()->assertJsonPath('data.status','ok')->assertJsonPath('data.response_metric','typed_leads')->assertJsonPath('data.allocations.0.source.conversion_definition.kind','lead');$this->assertLessThan(1500,$r->json('data.actual_response'));$run=OptimizationRun::findOrFail($r->json('data.run_id'));$this->assertArrayHasKey('typed_conversion_source',$run->source_snapshot['source_rows'][0]);TypedConversionDaily::where('conversion_definition_id',$d->id)->delete();$this->postJson('/api/v1/analytics/optimization-runs/'.$run->id.'/replay')->assertOk()->assertJsonPath('data.matches_archived_base_result',true);$this->postJson('/api/v1/analytics/entity-optimization',$base+['conversion_definition_id'=>$d->id])->assertJsonPath('data.status','incomplete_lead_history');
 }
 public function test_owned_viewer_cannot_write_and_fractional_semantics_are_explicit():void{
  [$u,$a,$c]=$this->fixture();$d=$this->definition($a);$u->removeRole('Owner');$u->assignRole('Viewer');$this->actingAs($u,'sanctum');$url='/api/v1/ad-accounts/'.$a->id.'/conversion-definitions/'.$d->id.'/daily-import';$row=['entity_id'=>$c->id,'date'=>now()->subDay()->toDateString(),'count'=>1.25,'currency'=>'USD','timezone'=>'UTC','source_reference'=>'fixture','retrieved_at'=>now()->format('Y-m-d\TH:i:sP')];$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row]])->assertForbidden();$u->assignRole('Owner');$d->update(['counting_method'=>'fractional_attributed']);$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row]])->assertOk();$this->assertEquals(1.25,TypedConversionDaily::where('conversion_definition_id',$d->id)->first()->count);$row['customer_email']='not-allowed';$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row]])->assertUnprocessable();
 }

 public function test_import_checks_completed_day_in_account_timezone():void{
  \Illuminate\Support\Carbon::setTestNow(\Illuminate\Support\Carbon::parse('2026-11-23T01:00:00Z'));
  try{[$u,$a,$c]=$this->fixture();$a->update(['timezone'=>'America/Los_Angeles']);$d=$this->definition($a);$this->actingAs($u,'sanctum');$row=['entity_id'=>$c->id,'date'=>'2026-11-22','count'=>1,'currency'=>'USD','timezone'=>'America/Los_Angeles','source_reference'=>'fixture','retrieved_at'=>now()->format('Y-m-d\TH:i:sP')];$url='/api/v1/ad-accounts/'.$a->id.'/conversion-definitions/'.$d->id.'/daily-import';$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row]])->assertUnprocessable();$row['date']='2026-11-21';$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row]])->assertOk();}finally{\Illuminate\Support\Carbon::setTestNow();}
 }

 public function test_import_cannot_silently_round_fractional_counts_or_assert_full_day_before_it_closed():void{
  [$u,$a,$c]=$this->fixture();$d=$this->definition($a);$d->update(['counting_method'=>'fractional_attributed']);$this->actingAs($u,'sanctum');$url='/api/v1/ad-accounts/'.$a->id.'/conversion-definitions/'.$d->id.'/daily-import';$row=['entity_id'=>$c->id,'date'=>now()->subDays(2)->toDateString(),'count'=>'1.23456','currency'=>'USD','timezone'=>'UTC','source_reference'=>'fixture','retrieved_at'=>now()->format('Y-m-d\TH:i:sP')];$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row]])->assertUnprocessable();$row['count']='1.2345';$row['retrieved_at']=now()->subDays(2)->setTime(12,0)->format('Y-m-d\TH:i:sP');$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row]])->assertUnprocessable();$row['retrieved_at']=now()->subDay()->startOfDay()->format('Y-m-d\TH:i:sP');$this->postJson($url,['entity_level'=>'campaign','rows'=>[$row]])->assertOk();$this->assertSame('1.2345',TypedConversionDaily::where('conversion_definition_id',$d->id)->first()->count);
 }
 public function test_definition_kind_foreign_owner_and_unmatched_population_do_not_enter_lead_optimizer():void{
  [$u,$a,$c]=$this->fixture();$d=$this->definition($a);$this->actingAs($u,'sanctum');$o=['entity_level'=>'campaign','objective'=>'MAXIMIZE_LEADS','budget'=>1000,'provider'=>'meta','conversion_definition_id'=>$d->id];$d->update(['kind'=>'purchase']);$this->postJson('/api/v1/analytics/entity-optimization',$o)->assertJsonPath('data.status','invalid_conversion_definition');$d->update(['kind'=>'lead']);TypedConversionDaily::create(['conversion_definition_id'=>$d->id,'entity_level'=>'campaign','entity_id'=>$c->id,'date'=>now()->subDay()->toDateString(),'count'=>10,'currency'=>'USD','timezone'=>'UTC','source_reference'=>'fixture','retrieved_at'=>now()]);$this->postJson('/api/v1/analytics/entity-optimization',$o)->assertJsonPath('data.status','incomplete_spend_history');$other=User::factory()->create();$this->actingAs($other,'sanctum')->postJson('/api/v1/analytics/entity-optimization',$o)->assertJsonPath('data.status','invalid_conversion_definition');
 }

 public function test_qualified_lead_objective_rejects_plain_leads_and_preserves_typed_units_both_solvers():void{
  config(['solver.python'=>\Tests\SolverRuntime::python($this)]);[$u,$a,$c]=$this->fixture();$d=$this->definition($a);$qualified=ConversionDefinition::create(array_merge($d->only(['connected_ad_account_id','name','counting_method','attribution_model','click_window_days','view_window_days','source_system']),['external_key'=>'qualified','kind'=>'qualified_lead']));for($i=30;$i>=1;$i--){$x=30+(30-$i)*10;$date=now()->subDays($i)->toDateString();PerformanceMetric::create(['metadata'=>['outcome_contract'=>['version'=>'source-outcomes-1','provider'=>'meta','count_metric'=>'synthetic-purchase','value_metric'=>'synthetic-purchase-value','attribution_basis'=>'synthetic-only','value_truth'=>'provider_reported_not_verified_sales','cross_source_equivalence'=>false],'normalization_version'=>'strict-operands-1','metric_definition'=>['normalization'=>'strict-meta-operands-1','account_metadata_source'=>'meta-discovery-explicit-1']],'connected_ad_account_id'=>$a->id,'campaign_id'=>$c->id,'provider'=>'meta','date'=>$date,'spend'=>$x,'impressions'=>1000,'clicks'=>100,'conversions'=>99999,'conversion_value'=>999999,'currency'=>'USD']);TypedConversionDaily::create(['conversion_definition_id'=>$qualified->id,'entity_level'=>'campaign','entity_id'=>$c->id,'date'=>$date,'count'=>round(20*(-expm1(-.01*$x))),'currency'=>'USD','timezone'=>'UTC','source_reference'=>'fixture','retrieved_at'=>now()]);}$this->actingAs($u,'sanctum');$o=['entity_level'=>'campaign','objective'=>'MAXIMIZE_QUALIFIED_LEADS','budget'=>4000,'provider'=>'meta'];$this->postJson('/api/v1/analytics/entity-optimization',$o)->assertUnprocessable();$this->postJson('/api/v1/analytics/entity-optimization',$o+['conversion_definition_id'=>$d->id])->assertJsonPath('data.status','invalid_conversion_definition');$ids=[];foreach(['continuous','discrete_milp']as$solver){$r=$this->postJson('/api/v1/analytics/entity-optimization',$o+['conversion_definition_id'=>$qualified->id,'solver'=>$solver,'budget_step'=>500,'maximum_active'=>1])->assertOk()->assertJsonPath('data.status','ok')->assertJsonPath('data.response_metric','typed_qualified_leads')->assertJsonPath('data.allocations.0.source.conversion_definition.kind','qualified_lead')->assertJsonPath('data.sensitivity.status','ok');$this->assertLessThan(600,$r->json('data.actual_response'));$ids[]=$r->json('data.run_id');}TypedConversionDaily::where('conversion_definition_id',$qualified->id)->delete();foreach($ids as$id)$this->postJson('/api/v1/analytics/optimization-runs/'.$id.'/replay')->assertJsonPath('data.matches_archived_base_result',true);
 }
}
